import { Alignment, Fit, Layout, Rive, RuntimeLoader, type StateMachineInput } from '@rive-app/canvas-lite';
import wasmUrl from '@rive-app/canvas-lite/rive.wasm?url';
import { memo, useEffect, useRef, useState, type CSSProperties } from 'react';
import rig from './rig.json';
import './coco.css';

// The runtime's WebAssembly is bundled with the app instead of fetched from a CDN.
RuntimeLoader.setWasmUrl(wasmUrl);
// coco.riv is generated by a script (tools/coco/build_riv.py) that writes classic state machine
// inputs; data binding would need view models in the file. Inputs work in this pinned runtime.
Rive.suppressDeprecationWarnings = ['state-machine-inputs'];

let bytesPromise: Promise<ArrayBuffer> | null = null;

/** coco.riv is downloaded once; each <Coco> parses its own copy, so unmounting one never
 * disturbs another. */
export function loadCocoBytes(): Promise<ArrayBuffer> {
  if (!bytesPromise) {
    bytesPromise = fetch(`${import.meta.env.BASE_URL}coco.riv`).then((r) => {
      if (!r.ok) throw new Error(`coco.riv: HTTP ${r.status}`);
      return r.arrayBuffer();
    });
    bytesPromise.catch(() => (bytesPromise = null));
  }
  return bytesPromise;
}

export type CocoMode = 'stand' | 'perch' | 'fly';
export type CocoCue = { kind: 'look' | 'excite'; id: number } | null;

export interface CocoProps {
  /** stand: idle on the ground; perch: settled on a perch; fly: takes off and flies. */
  mode?: CocoMode;
  /** A one-off action; fires again whenever `id` changes. */
  cue?: CocoCue;
  facing?: 'right' | 'left';
  /** Hold the rest pose (reduced motion, or a paused story). */
  still?: boolean;
  /** 0..1: how much Coco reads as a dark ink silhouette. */
  silhouette?: number;
  className?: string;
  style?: CSSProperties;
  /** Accessible description; Coco is decorative when omitted. */
  label?: string;
}

/**
 * Coco, drawn by the Rive runtime from public/coco.riv (artboard and state machine "Coco",
 * built by tools/coco/build_riv.py). The box keeps the artboard's 9:10 aspect; size it with
 * CSS (height or width). The feet sit at 93 % of the height, centred.
 */
export const Coco = memo(function Coco({
  mode = 'stand',
  cue = null,
  facing = 'right',
  still = false,
  silhouette = 0,
  className,
  style,
  label,
}: CocoProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const riveRef = useRef<Rive | null>(null);
  const inputsRef = useRef<Record<string, StateMachineInput>>({});
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    let rive: Rive | null = null;
    const canvas = canvasRef.current!;
    const observer = new ResizeObserver(() => rive?.resizeDrawingSurfaceToCanvas(Math.min(window.devicePixelRatio || 1, 2)));
    loadCocoBytes()
      .then((buffer) => {
        if (cancelled) return;
        rive = new Rive({
          buffer,
          canvas,
          artboard: rig.artboard,
          stateMachine: rig.stateMachine,
          autoplay: true,
          layout: new Layout({ fit: Fit.Contain, alignment: Alignment.Center }),
          shouldDisableRiveListeners: true,
          enableRiveAssetCDN: false,
          onLoad: () => {
            if (cancelled || !rive) return;
            rive.resizeDrawingSurfaceToCanvas(Math.min(window.devicePixelRatio || 1, 2));
            const inputs: Record<string, StateMachineInput> = {};
            for (const input of rive.stateMachineInputs(rig.stateMachine) ?? []) inputs[input.name] = input;
            inputsRef.current = inputs;
            riveRef.current = rive;
            setReady(true);
          },
        });
        observer.observe(canvas);
      })
      .catch((err) => console.error(err));
    return () => {
      cancelled = true;
      observer.disconnect();
      rive?.cleanup();
      riveRef.current = null;
      inputsRef.current = {};
      setReady(false);
    };
  }, []);

  // mode -> the state machine's two booleans
  useEffect(() => {
    if (!ready) return;
    const { flying, perched } = inputsRef.current;
    if (flying) flying.value = mode === 'fly';
    if (perched) perched.value = mode === 'perch';
  }, [ready, mode]);

  useEffect(() => {
    if (!ready || !cue) return;
    inputsRef.current[cue.kind]?.fire();
  }, [ready, cue?.id, cue?.kind]); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    const rive = riveRef.current;
    if (!ready || !rive) return;
    if (still) rive.pause();
    else rive.play();
  }, [ready, still]);

  const s = Math.min(Math.max(silhouette, 0), 1);
  return (
    <div
      className={`coco${facing === 'left' ? ' coco--left' : ''}${ready ? ' coco--ready' : ''}${className ? ` ${className}` : ''}`}
      style={{ ...style, ...(s > 0 ? { filter: `brightness(${1 - s * 0.88}) saturate(${1 - s})` } : null) }}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
    >
      <canvas ref={canvasRef} />
    </div>
  );
});

export const COCO_DURATIONS = rig.durations;
/** The artboard's aspect (width / height) and where the feet are, as fractions of the box. */
export const COCO_ASPECT = rig.size[0] / rig.size[1];
export const COCO_FEET = { x: rig.feet[0] / rig.size[0], y: rig.feet[1] / rig.size[1] };
